\version "2.27.2"
% automatically converted by musicxml2ly from 43c-MultiStaff-DifferentKeysAfterBackup.xml
\pointAndClickOff

\header {
  texidoc = "A piano staff with different keys and clefs for each of its staves.
    The key and clef for the second staff is given only after a <backup>
    element, just before the first note of the second staff, but after the whole
    measure for staff one has been output."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative f' {
  \clef "treble" \numericTimeSignature \time 4/4 \key c \major f1 }

PartPOneVoiceTwo = \relative b, {
  \numericTimeSignature \time 4/4 \clef "bass" \key d \major b1 }


% The score definition
\score {
  <<
    \new PianoStaff = "P1" <<
      \context Staff = "1" <<
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
      \context Staff = "2" <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceTwo" {
          \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
